// Visual transitions observe rules state; they never apply damage or move game cards.
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const $=s=>document.querySelector(s);
const nodes=()=>[...document.querySelectorAll('#app [data-motion-uid]')];
const rect=el=>el?.getBoundingClientRect();
const center=r=>({x:r.left+r.width/2,y:r.top+r.height/2});
// Waits for a promise, but never longer than ms. Resolves {done:true,value} or {done:false}; a rejection before the deadline propagates.
export function within(promise,ms,{schedule=setTimeout,cancel=clearTimeout}={}){let timer;const late=new Promise(resolve=>{timer=schedule(()=>resolve({done:false}),ms);});return Promise.race([Promise.resolve(promise).then(value=>({done:true,value})),late]).finally(()=>cancel(timer));}
// A background tab can leave an animation's `finished` unsettled until it next paints, so every wait is capped by a timer.
export function settle(animation,duration,slack=400){return within(animation.finished.catch(()=>{}),duration+slack);}
// Nothing is visible to animate in a hidden tab.
const still=()=>reduced()||document.hidden;
function animate(el,frames,duration){const ms=reduced()?1:duration;return settle(el.animate(frames,{duration:ms,easing:'cubic-bezier(.2,.7,.2,1)',fill:'both'}),ms);}
function ghost(item){const el=item.el.cloneNode(true);el.removeAttribute('id');el.removeAttribute('data-motion-uid');el.removeAttribute('data-card');el.setAttribute('aria-hidden','true');el.classList.add('motion-ghost');Object.assign(el.style,{left:`${item.r.left}px`,top:`${item.r.top}px`,width:`${item.r.width}px`,height:`${item.r.height}px`,margin:'0',transform:'none'});document.body.append(el);return el;}
export function snapshot(game){const cards=new Map();game.players.forEach((p,owner)=>['hand','field','grave'].forEach(zone=>p[zone].forEach(c=>cards.set(c.uid,{zone,owner}))));game.stack.forEach(s=>cards.set(s.card.uid,{zone:'stack',owner:s.p}));const visual=new Map(nodes().map(el=>[Number(el.dataset.motionUid),{el,r:rect(el)}]));return {cards,visual,phase:game.phase,attacks:[...game.attacks],blocks:structuredClone(game.blocks),active:game.active,decks:[0,1].map(p=>rect($(`[data-player="${p}"] .deck-pile`))),graves:[0,1].map(p=>rect($(`[data-grave="${p}"]`))),players:[0,1].map(p=>rect($(`[data-player="${p}"]`)))};}
async function impact(r){if(!r)return;const p=center(r),ring=document.createElement('div');ring.className='impact-ring';ring.style.left=`${p.x}px`;ring.style.top=`${p.y}px`;document.body.append(ring);await animate(ring,[{transform:'translate(-50%,-50%) scale(.2)',opacity:1},{transform:'translate(-50%,-50%) scale(2.4)',opacity:0}],360);ring.remove();}
export async function combat(before,game){if(before.phase!=='afterBlock'||game.phase!=='endCombat'||still())return;await Promise.all(before.attacks.map(async uid=>{const from=before.visual.get(uid);if(!from)return;const targets=(before.blocks[uid]||[]).map(id=>before.visual.get(id)).filter(Boolean);const destinations=targets.length?targets:[{r:before.players[1-before.active]}];const g=ghost(from);from.el.style.visibility='hidden';try{for(const target of destinations){if(!target.r)continue;const a=center(from.r),b=center(target.r),x=b.x-a.x,y=b.y-a.y;await animate(g,[{transform:'perspective(800px) translate3d(0,0,0) rotateX(0)'},{transform:`perspective(800px) translate3d(${x*.9}px,${y*.9}px,65px) rotateX(${y>0?-14:14}deg) rotateZ(-4deg)`}],310);await Promise.all([impact(target.r),target.el?animate(target.el,[{transform:'translateX(0)'},{transform:'translateX(9px) rotate(4deg)'},{transform:'translateX(-5px)'},{transform:'translateX(0)'}],260):Promise.resolve()]);await animate(g,[{transform:`translate(${x*.9}px,${y*.9}px) scale(1.06)`},{transform:'translate(0,0) scale(1)'}],220);}}finally{g.remove();from.el.style.visibility='';}}));}
async function depart(item,target,destroyed){const g=ghost(item);try{if(destroyed){const particles=Array.from({length:18},(_,i)=>{const p=document.createElement('i');p.className='dissolve-particle';const x=item.r.left+(i%6+.5)*item.r.width/6,y=item.r.top+(Math.floor(i/6)+.5)*item.r.height/3;p.style.left=`${x}px`;p.style.top=`${y}px`;document.body.append(p);return animate(p,[{opacity:1,transform:'translate(0,0) scale(1)'},{opacity:0,transform:`translate(${(i%5-2)*27}px,${-45-(i%4)*18}px) scale(0)`}],640).then(()=>p.remove());});await Promise.all([animate(g,[{opacity:1,filter:'brightness(1)',clipPath:'inset(0 0 0 0)'},{offset:.4,opacity:.85,filter:'brightness(2.7)',clipPath:'inset(0 0 22% 0)'},{opacity:0,filter:'brightness(3) blur(5px)',clipPath:'inset(0 0 100% 0)'}],640),...particles]);}else{const a=center(item.r),b=target?center(target):a;await animate(g,[{transform:'perspective(700px) rotateY(0) scale(1)',opacity:1},{offset:.45,transform:'perspective(700px) rotateY(65deg) rotateZ(-18deg) scale(.55,.8)',filter:'brightness(.65)',opacity:1},{transform:`perspective(700px) translate(${b.x-a.x}px,${b.y-a.y}px) rotateY(150deg) rotateZ(48deg) scale(.05,.12)`,opacity:0}],650);}}finally{g.remove();}}
export async function transitions(before,game){if(still())return;const after=snapshot(game),jobs=[];for(const [uid,now] of after.cards){const old=before.cards.get(uid),item=after.visual.get(uid);if(now.zone==='grave'&&old&&old.zone!=='grave'){let from=before.visual.get(uid);if(!from&&old.zone==='hand'&&old.owner===1&&before.players[1]){const el=document.createElement('div');el.className='card hidden-card '+game.players[old.owner].faction;const r=before.players[1];from={el,r:{left:r.left+r.width/2,top:r.top,width:90,height:125}};}if(from)jobs.push(depart(from,after.graves[now.owner],old.zone==='field'));}if(item&&(!old||old.zone!==now.zone)&&now.zone!=='grave'){const origin=before.visual.get(uid)?.r||(now.zone==='hand'?before.decks?.[now.owner]:null)||before.players[now.owner],a=center(item.r),b=origin?center(origin):{x:a.x-90,y:a.y+80};const g=ghost(item);item.el.style.visibility='hidden';g.classList.add('entry-card');const back=document.createElement('div');back.className='card-back '+game.players[now.owner].faction;g.append(back);jobs.push(animate(g,[{transform:`perspective(850px) translate3d(${b.x-a.x}px,${b.y-a.y}px,0) rotateY(180deg) rotateZ(-10deg) scale(.7)`,opacity:0},{offset:.18,opacity:1},{offset:.7,transform:'perspective(850px) translate3d(0,-12px,70px) rotateY(20deg) rotateZ(2deg) scale(1.05)',opacity:1},{transform:'perspective(850px) translate3d(0,0,0) rotateY(0) rotateZ(0) scale(1)',opacity:1}],620).finally(()=>{g.remove();item.el.style.visibility='';}));}}await Promise.all(jobs);}
let arrowFrame=0;
export function arrows(assignments){cancelAnimationFrame(arrowFrame);arrowFrame=requestAnimationFrame(()=>{document.querySelector('.block-arrows')?.remove();if(!$('.table'))return;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('block-arrows');svg.setAttribute('aria-hidden','true');svg.innerHTML='<defs><marker id="block-tip" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#9a640c"/></marker></defs>';for(const [attacker,blockers] of Object.entries(assignments))for(const uid of blockers){const from=$(`[data-motion-uid="${uid}"][data-zone="field"]`),to=$(`[data-motion-uid="${attacker}"][data-zone="field"]`);if(!from||!to)continue;const fr=rect(from),tr=rect(to),visible=(el,r)=>{const row=rect(el.closest('.board-row'));return row&&r.right>row.left&&r.left<row.right;};if(!visible(from,fr)||!visible(to,tr))continue;const a=center(fr),b=center(tr),direction=b.y>a.y?1:-1;a.y+=direction*fr.height/2;b.y-=direction*(tr.height/2+7);const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',`M ${a.x} ${a.y} C ${a.x} ${(a.y+b.y)/2}, ${b.x} ${(a.y+b.y)/2}, ${b.x} ${b.y}`);path.setAttribute('marker-end','url(#block-tip)');svg.append(path);}document.body.append(svg);});}
